// People placed in the world (S1a, T5, T7, T4, G6, T6, G8, T8, L4). Tile coordinates; face 0 down, 2 right, 4 up, 6 left. Every line grounded in the bible (Goldacre, Salt Bay, Pinegrove, Spindlewood, Routes 3, 5, 7, 8, 9, 10, 111) or plain greeting / weather flavour. A Skill teacher has script 'teach', skill, lines (the offer) and known (after).
// { id, x, y, sprite (TRAINER_OW8 key), face, move: 'still' | 'wander' | 'path', path?: [[x, y], ...], r?: wander radius in tiles, name?, lines: [page, ...], trainer?: { cls, name, team: [[species, rel]], sight, money, say, lose } }
// A trainer team scales with the challenger's badges: level = route cap-5 + rel (rel 0..3, see ADVN.range), the first N entries by band size, species evolved to match. money = payout per level of the strongest mon.
window.ADV_NPCS = [
  // ---------- Goldacre: villagers ----------
  { id: 'g7-granny', x: 297, y: 873, sprite: 'npc3-old-woman-cane', face: 2, move: 'still', lines: ['Miss Whitney came all the way from Johto. She named our town after her old one.', 'Goldenrod got too big for her, they say. Out here she has all the land she wants.'] },
  { id: 'g7-farmer', x: 302, y: 874, sprite: 'npc3-bearded-man', face: 6, move: 'wander', r: 2, lines: ['Our fields have no fences and no gates. Goldacre trusts people, and it has never gone wrong.'] },
  { id: 'g7-kid', x: 304, y: 883, sprite: 'npc2-red-shirt-boy', face: 4, move: 'wander', r: 3, lines: ['That big red barn is the gym! Miss Whitney has a Miltank that is really scary.'] },
  { id: 'g7-woman', x: 294, y: 887, sprite: 'npc3-apron-woman', face: 0, move: 'wander', r: 3, lines: ['Someone really ought to organise a harvest festival. We certainly have the harvest for it.'] },
  { id: 'g7-turbine', x: 302, y: 890, sprite: 'npc2-jumpsuit-man', face: 2, move: 'still', lines: ['Those turbines out on Route 7 make our power. We sell what we do not use.'] },
  { id: 'g7-youngster', x: 296, y: 864, sprite: 'npc1-blue-haired-boy', face: 0, move: 'wander', r: 3, lines: ['Stay off Route 7 after dark. Houndour come down onto the open pasture at night.'] },
  { id: 'g7-bibarel', x: 295, y: 848, sprite: 'fishing', face: 4, move: 'still', lines: ['Bidoof build dams up Route 8 and the meadows go wet. The ford is not reliable, so we built a bridge.'] },
  { id: 'g7-delivery', x: 302, y: 896, sprite: 'delivery', face: 4, move: 'wander', r: 2, lines: ['In season the vans run down to Longshore every day. Everyone eats what we grow.'] },
  { id: 'g7-cowgirl', x: 312, y: 873, sprite: 'cowgirl', face: 0, move: 'wander', r: 2, lines: ['Miltank run wild on Route 5. Miss Whitney picked her ace from a field on that road.'] },
  { id: 'g7-cherubi', x: 309, y: 865, sprite: 'npc3-cap-girl', face: 2, move: 'wander', r: 3, lines: ['Cherubi turn up in our crop fields. Just like the Cherimart mascot!'] },
  { id: 'g7-sky', x: 285, y: 882, sprite: 'npc3-apron-woman', face: 0, move: 'wander', r: 3, lines: ['What a lot of sky today. I never get tired of it.'] },

  // ---------- Route 5: the open fields (youngsters, lasses) ----------
  { id: 'r5-cal', x: 334, y: 827, sprite: 'npc2-red-shirt-boy', face: 0, move: 'still', lines: ['Nothing out here is fenced off. People just walk through the fields.'],
    trainer: { cls: 'Youngster', name: 'Cal', sight: 5, money: 16, team: [['wooloo', 0], ['bunnelby', 1], ['wooloo', 1], ['bunnelby', 2], ['wooloo', 3], ['bunnelby', 3]], say: 'Route 5 is the safest road in Kenora. Perfect for a warm-up battle!', lose: 'Wow, you are strong!' } },
  { id: 'r5-jenna', x: 360, y: 834, sprite: 'npc4-ponytail-girl', face: 6, move: 'still', lines: ['They say Whitney picked her Miltank out of a field on this very road.'],
    trainer: { cls: 'Lass', name: 'Jenna', sight: 5, money: 24, team: [['bunnelby', 0], ['combee', 1], ['wooloo', 1], ['nickit', 2], ['combee', 2], ['wooloo', 3]], say: 'Hedges on both sides of the road. You cannot sneak past me!', lose: 'Oh no, I lost!' } },
  { id: 'r5-dee', x: 388, y: 829, sprite: 'npc3-cap-girl', face: 2, move: 'still', lines: ['Goldacre trusts everyone. I guess that is why there are no gates.'],
    trainer: { cls: 'Picnicker', name: 'Dee', sight: 5, money: 24, team: [['wooloo', 0], ['miltank', 1], ['bunnelby', 2], ['miltank', 2], ['wooloo', 3], ['miltank', 3]], say: 'The fields are lovely today. Let us battle!', lose: 'That was fun. You win!' } },
  { id: 'r5-ned', x: 404, y: 825, sprite: 'npc4-brown-haired-boy', face: 4, move: 'still', lines: ['The hedge has gaps every so often. Handy for spotting people.'],
    trainer: { cls: 'Youngster', name: 'Ned', sight: 5, money: 16, team: [['bunnelby', 0], ['wooloo', 1], ['bouffalant', 2], ['bunnelby', 2], ['tepig', 3], ['bouffalant', 3]], say: 'You can see forever from this road. And I can see you!', lose: 'I should have hidden behind a hedge.' } },

  // ---------- Route 21: the Eastern Ridge (map-lab pilot 3; hikers on the roads below the massifs, a hut keeper). Flavour lines only. ----------
  { id: 'r21-hut', x: 839, y: 426, sprite: 'npc5-camo-man', face: 0, move: 'still', lines: ['Quiet up here. The wind off the ridge keeps the hut cool all summer.', 'Take the stairs slowly. The rock is loose near the top.'] },
  { id: 'r21-tor', x: 832, y: 436, sprite: 'npc1-explorer', face: 2, move: 'still', lines: ['I climb both massifs every morning. The west one has the better view.'],
    trainer: { cls: 'Hiker', name: 'Tor', sight: 4, money: 24, team: [['aron', 0], ['nacli', 1], ['aron', 1], ['rockruff', 2], ['nacli', 2], ['cufant', 3]], say: 'Legs warmed up? Mine are. Let us battle!', lose: 'The ridge was easier than you.' } },
  { id: 'r21-kai', x: 838, y: 444, sprite: 'north-headband-brawler', face: 6, move: 'still', lines: ['I train on the stairs. Up and down, up and down.'],
    trainer: { cls: 'Black Belt', name: 'Kai', sight: 4, money: 24, team: [['nickit', 0], ['rockruff', 1], ['nickit', 1], ['hawlucha', 2], ['rockruff', 2], ['hawlucha', 3]], say: 'Hyah! Show me your strength!', lose: 'Hngh. More stair training for me.' } },
  { id: 'r21-wren', x: 820, y: 446, sprite: 'npc4-ponytail-girl', face: 0, move: 'still', lines: ['There is a cave in the east cliff. I am not going in without a light.'],
    trainer: { cls: 'Picnicker', name: 'Wren', sight: 4, money: 20, team: [['nickit', 0], ['aron', 1], ['nacli', 1], ['nickit', 2], ['aron', 2], ['cufant', 3]], say: 'You came down the road? Then you have to battle me!', lose: 'Aww. Good battle though.' } },

  // ---------- Route 22: the orchard road (map-lab pilot 1; villagers). Flavour lines only. ----------
  { id: 'r22-keeper', x: 871, y: 492, sprite: 'npc3-apron-woman', face: 4, move: 'still', lines: ['The orchard trees want picking every few days in season. My back knows it.'] },
  { id: 'r22-bench', x: 869, y: 497, sprite: 'npc2-old-man', face: 2, move: 'still', lines: ['I come and sit by the orchard gate. Nothing much happens, and that suits me.'] },
  { id: 'r22-walker', x: 845, y: 476, sprite: 'npc1-explorer', face: 6, move: 'still', lines: ['There is an old ruined gate out in the west meadow. Nobody knows who built it.'] },
  { id: 'r22-kid', x: 853, y: 479, sprite: 'npc4-vest-boy', face: 0, move: 'wander', r: 2, lines: ['I am looking for Combee. They like the flowers by the road.'] },
  { id: 'r22-stall', x: 873, y: 496, sprite: 'npc1-red-cap-man', face: 0, move: 'still', lines: ['Fresh off the trees this morning. Best fruit on the whole road.'] },
  { id: 'r22-pond', x: 856, y: 472, sprite: 'npc4-ponytail-girl', face: 0, move: 'still', lines: ['The pond is so still today. You can see every cloud in it.'] },

  // ---------- Route 7: the grazing country (ranchers, hikers) ----------
  { id: 'r7-walt', x: 226, y: 930, sprite: 'npc2-bearded-man', face: 0, move: 'still', lines: ['Those turbines sell power all over. Goldacre makes more than it needs.'],
    trainer: { cls: 'Rancher', name: 'Walt', sight: 5, money: 24, team: [['mareep', 0], ['mareep', 1], ['smoliv', 1], ['mareep', 2], ['smoliv', 2], ['mareep', 3]], say: 'Stock grazes all over Route 7. Mind you do not startle my Mareep!', lose: 'Fair fight. You win.' } },
  { id: 'r7-gus', x: 249, y: 940, sprite: 'npc1-explorer', face: 6, move: 'still', script: 'coach', skill: 'rough', name: 'Gus', time: 22, course: [[234, 932], [241, 929], [248, 932], [251, 936]], coach: ['Rough ground suits a heavy mount. I can teach you.', 'Pay me, take the hard lesson, or ride my course against the clock.'], known: ['You ride rough ground well. Keep at it.'], lines: ['Houndour come down onto the pasture at night. I would not camp out here.'],
    trainer: { cls: 'Hiker', name: 'Gus', sight: 5, money: 24, team: [['rockruff', 0], ['mankey', 1], ['rockruff', 1], ['mankey', 2], ['rockruff', 2], ['mankey', 3]], say: 'The ground gets rough up here. Good country for a hiker!', lose: 'My legs are stronger than my Pokemon.' } },
  { id: 'r7-dolly', x: 270, y: 932, sprite: 'cowgirl', face: 0, move: 'still', script: 'coach', skill: 'canter', name: 'Dolly', time: 32, course: [[276, 931], [270, 938], [258, 938], [252, 928], [258, 918], [270, 918]], coach: ['Wide open grazing land is made for a canter. I can teach you.', 'Pay me, take the hard lesson, or ride my course against the clock.'], known: ['You canter well. The open land is yours.'], lines: ['You can hear the turbines the whole way along this road.'],
    trainer: { cls: 'Rancher', name: 'Dolly', sight: 5, money: 24, team: [['mareep', 0], ['smoliv', 1], ['mareep', 1], ['seviper', 2], ['smoliv', 2], ['mareep', 3]], say: 'Wide open grazing land. Nowhere to hide, is there?', lose: 'You rode me right out of the saddle!' } },
  { id: 'r7-ike', x: 295, y: 944, sprite: 'npc1-explorer', face: 2, move: 'still', script: 'coach', skill: 'boulder', name: 'Ike', time: 24, course: [[281, 934], [286, 925], [294, 925], [298, 927]], coach: ['The edges of this road are all hills and rocks. I can teach you to ride them.', 'Pay me, take the hard lesson, or ride my course against the clock.'], known: ['You ride the rocks well. Keep at it.'], lines: ['Route 7 is rougher than Route 5. Little hills and rocks at the edges.'],
    trainer: { cls: 'Hiker', name: 'Ike', sight: 5, money: 24, team: [['mankey', 0], ['rockruff', 1], ['houndour', 1], ['mankey', 2], ['houndour', 2], ['rockruff', 3]], say: 'Hear that whirring? The turbines will keep us company.', lose: 'Whew. You wore me out.' } },

  // ---------- Route 8: the river bottom (farmers, fishermen) ----------
  { id: 'r8-abel', x: 254, y: 793, sprite: 'npc3-old-man-cane', face: 4, move: 'still', lines: ['Bibarel keep shifting the water table. You cannot count on the ford.'],
    trainer: { cls: 'Farmer', name: 'Abel', sight: 5, money: 20, team: [['bidoof', 0], ['wooper', 1], ['bidoof', 1], ['marill', 2], ['wooper', 2], ['bidoof', 3]], say: 'These water meadows are wet underfoot. The Bidoof see to that!', lose: 'Wet and beaten. That is me.' } },
  { id: 'r8-dale', x: 264, y: 805, sprite: 'fishing', face: 0, move: 'still', lines: ['The river is wide here. Use the bridge unless you like wet boots.'],
    trainer: { cls: 'Fisherman', name: 'Dale', sight: 5, money: 20, team: [['krabby', 0], ['staryu', 1], ['krabby', 1], ['mareanie', 2], ['staryu', 2], ['mareanie', 3]], say: 'Nothing is biting, so I will take you on instead!', lose: 'Not even a nibble all day.' } },
  { id: 'r8-wes', x: 277, y: 819, sprite: 'fishing2', face: 6, move: 'still', lines: ['The water table moves, so the ford cannot be trusted.'],
    trainer: { cls: 'Fisherman', name: 'Wes', sight: 5, money: 20, team: [['psyduck', 0], ['buizel', 1], ['krabby', 1], ['palpitoad', 2], ['buizel', 2], ['totodile', 3]], say: 'I am waiting on a bite. A battle will pass the time!', lose: 'Reel me in. I am done.' } },
  { id: 'r8-boyd', x: 296, y: 828, sprite: 'npc2-striped-shirt-man', face: 6, move: 'still', lines: ['Goldacre built the bridge because of the ford. You will see why.'],
    trainer: { cls: 'Farmer', name: 'Boyd', sight: 5, money: 20, team: [['wooper', 0], ['bidoof', 1], ['marill', 1], ['wooper', 2], ['marill', 2], ['bidoof', 3]], say: 'My meadows are soaked all year. Good thing Bidoof like it!', lose: 'Soaked and beaten.' } },
  { id: 'r8-gil', x: 250, y: 793, sprite: 'npc1-green-shirt-man', face: 0, move: 'still', lines: ['Willow trees all along here. Good shade for a rest.'],
    trainer: { cls: 'Rancher', name: 'Gil', sight: 5, money: 24, team: [['marill', 0], ['bidoof', 1], ['buizel', 1], ['grookey', 2], ['marill', 2], ['wooper', 3]], say: 'A trainer on the river road! Let us go!', lose: 'You have a strong team.' } },
  // ---------- Salt Bay: the fishing village (two Skill teachers on the piers, villagers) ----------
  { id: 's5-surf', x: 104, y: 796, sprite: 'npc4-sailor', face: 6, move: 'still', script: 'teach', skill: 'surf', name: 'Surf teacher', lines: ['Twenty metres out the ground is simply gone. That is why we teach surfing properly.', 'Mind the deep water. Do you want to learn how to cross it?'], known: ['You know how now. Keep a calm head out there, the bay has no bottom.'] },
  { id: 's5-fish', x: 106, y: 804, sprite: 'fishing2', face: 6, move: 'still', script: 'teach', skill: 'fishing', name: 'Fishing teacher', lines: ['Four generations of my family have done nothing but fish. Want to learn?', 'Here is a rod. Sit still and be patient.'], known: ['The rod is yours. Face the water, cast, and be patient.'] },
  { id: 's5-measure', x: 124, y: 789, sprite: 'npc2-striped-shirt-man', face: 0, move: 'wander', r: 2, lines: ['Someone tried to measure the bay once. Everyone here can tell it.','I tell it better than most. Nobody has tried since, though.'] },
  { id: 's5-feebas', x: 152, y: 806, sprite: 'fishing', face: 0, move: 'wander', r: 2, lines: ['Feebas is our legend. Every fisherman here has an opinion about where it bites.'] },
  { id: 's5-net', x: 126, y: 780, sprite: 'npc2-purple-top-woman', face: 0, move: 'wander', r: 2, lines: ['Nets, boats, racks. That is Salt Bay. We are not struggling, we have what we need.'] },
  { id: 's5-kid', x: 128, y: 802, sprite: 'npc2-yellow-shirt-boy', face: 0, move: 'wander', r: 1, lines: ['The road ends at the water. People only come here on purpose, or by mistake.'] },
  { id: 's5-night', x: 104, y: 799, sprite: 'npc3-old-woman-cane', face: 6, move: 'still', lines: ['At night something glows under the water. Lanturn, lit up from below.'] },
  { id: 's5-quiet', x: 141, y: 806, sprite: 'npc1-red-cap-man', face: 0, move: 'wander', r: 2, lines: ['The catch is thin. Deep cold water holds little, so we take what comes.'] },

  // ---------- Route 9: the working shore (nets, boats, drying racks; a stranger teaches fishing before you reach town) ----------
  { id: 'r9-teacher', x: 187, y: 803, sprite: 'npc5-old-man', face: 0, move: 'still', script: 'teach', skill: 'fishing', name: 'Fisherman', lines: ['Everyone on this road fishes, and we like to teach. Do you want to learn?', 'Take this rod. Cast it at the water and wait.'], known: ['Face the water and press F to cast. People are fishing the whole length of this road.'] },
  { id: 'r9-hal', x: 180, y: 791, sprite: 'fishing', face: 0, move: 'still', lines: ['Nets, racks, boats. This is a working shore, not a holiday.'],
    trainer: { cls: 'Fisherman', name: 'Hal', avatar: 'fisherman', sight: 5, money: 20, team: [['magikarp',0],['wimpod',1],['krabby',1],['carvanha',2],['chinchou',2],['marill',3]], say: 'I have fished this shore all my life. Let me show you what bites!', lose: 'The big one got away again.' } },
  { id: 'r9-moss', x: 197, y: 802, sprite: 'npc4-sailor', face: 4, move: 'still', lines: ['People are fishing the whole length of this road. Stop and ask, they will teach you.'],
    trainer: { cls: 'Sailor', name: 'Moss', avatar: 'sailor', sight: 5, money: 20, team: [['wingull',0],['wimpod',1],['wingull',1],['carvanha',2],['wimpod',2],['carvanha',3]], say: 'Salt Bay is a working shore. No tourists, no kiosks, just us!', lose: 'Overboard I go.' } },
  { id: 'r9-finn', x: 214, y: 791, sprite: 'fishing2', face: 0, move: 'still', lines: ['Mind the nets on the bank. They are mending, not decoration.'],
    trainer: { cls: 'Fisherman', name: 'Finn', avatar: 'fisherman', sight: 5, money: 20, team: [['magikarp',0],['marill',1],['magikarp',1],['krabby',2],['chinchou',2],['mudkip',3]], say: 'The drying racks do not fill themselves. Battle first, chat after!', lose: 'You reeled me in.' } },
  { id: 'r9-pru', x: 229, y: 804, sprite: 'npc4-sailor', face: 4, move: 'still', lines: ['The boats sit up on the bank when they are not out.'],
    trainer: { cls: 'Sailor', name: 'Pru', avatar: 'sailor', sight: 5, money: 20, team: [['marill',0],['wingull',1],['wimpod',1],['krabby',2],['carvanha',2],['chinchou',3]], say: 'Boats, nets, racks. We have everything but visitors!', lose: 'Fair winds to you.' } },

  // ---------- Route 10: the lakeside (the campsite and its register; Nickit and Purrloin own the night) ----------
  { id: 'r10-register', x: 262, y: 716, sprite: null, face: 0, move: 'still', name: 'Campsite register', lines: ['The campsite register. There are three other names in it.', 'You sign your own name below theirs.'] },
  { id: 'r10-gossip', x: 265, y: 713, sprite: 'npc1-backwards-cap-boy', face: 0, move: 'still', lines: ['A trainer came through last week. Tall, I think. Or maybe short. It was a while ago.','Anyway, they signed the register like everyone else.'] },
  { id: 'r10-owen', x: 248, y: 775, sprite: 'npc1-headband-boy', face: 2, move: 'still', lines: ['Sign the register at the campsite. Everyone does, it is only polite.'],
    trainer: { cls: 'Camper', name: 'Owen', avatar: 'camper', sight: 5, money: 16, team: [['ducklett',0],['skiddo',1],['nickit',1],['purrloin',2],['pikachu',2],['ducklett',3]], say: 'I pitched here this morning. Fancy a battle before supper?', lose: 'Supper time already.' } },
  { id: 'r10-mara', x: 261, y: 758, sprite: 'npc1-ponytail-girl', face: 6, move: 'still', lines: ['Both shore and lake Pokemon turn up along this road.'],
    trainer: { cls: 'Picnicker', name: 'Mara', avatar: 'picnicker', sight: 5, money: 24, team: [['ducklett',0],['skiddo',1],['lotad',1],['marill',2],['pikachu',2],['bulbasaur',3]], say: 'The lake is lovely out here. Salt at one end, fresh at the other!', lose: 'Oh well, back to my picnic.' } },
  { id: 'r10-reed', x: 248, y: 740, sprite: 'fishing', face: 2, move: 'still', lines: ['I fish the lakeshore. Feebas is Salt Bay only, they say.'],
    trainer: { cls: 'Fisherman', name: 'Reed', avatar: 'fisherman', sight: 5, money: 20, team: [['magikarp',0],['lotad',1],['marill',1],['piplup',2],['magikarp',2],['marill',3]], say: 'Nothing is biting, so you will do.', lose: 'Not a nibble all day.' } },
  { id: 'r10-pip', x: 259, y: 730, sprite: 'npc1-headband-boy', face: 6, move: 'still', lines: ['Everyone leaves their bags out on this road. I do not know why I trust them.'],
    trainer: { cls: 'Camper', name: 'Pip', avatar: 'camper', sight: 5, money: 16, team: [['nickit',0],['purrloin',1],['ducklett',1],['skiddo',2],['nickit',2],['purrloin',3]], say: 'Nickit and Purrloin come out at night. I keep an eye on my bag!', lose: 'Mind my bag while I recover.' } },

  // ---------- Longshore: the beach resort (ice cream, a lifeguard, hire kiosks; the Sandygast castles and the dock are up the coast on the Route 6 strip) ----------
  { id: 't7-ice', x: 129, y: 954, sprite: 'shopm2', face: 4, move: 'still', lines: ['Ice cream! Best job in Kenora, and I would not swap it.', 'Everything on this boardwalk came down Route 6 from the farms.'] },
  { id: 't7-guard', x: 114, y: 961, sprite: 'sportsman', face: 6, move: 'still', lines: ['Past the buoys is Sharpedo water. Everyone ignores the signs.', 'Nothing has ever happened, so nobody listens.'] },
  { id: 't7-kid', x: 110, y: 953, sprite: 'npc1-backwards-cap-boy', face: 6, move: 'wander', r: 2, lines: ['The water only comes up to my chest, even way out past the buoys!', 'Mum says that is far enough. I say it is not.'] },
  { id: 't7-hire', x: 117, y: 965, sprite: 'npc3-pikachu-kid', face: 4, move: 'still', script: 'class', skill: 'surf', name: 'Board hire', fee: 800, lines: ['Hire a board and ride it badly. Everybody shouts, it is great fun.', 'I can show you the basics of surfing. Want a lesson?'], known: ['You can stay on a board now. Salt Bay folk say they teach it properly, too.'] },
  { id: 't7-van', x: 124, y: 951, sprite: 'delivery', face: 0, move: 'wander', r: 1, lines: ['Vans down from Goldacre all summer. Fruit, veg, milk, the lot.'] },
  { id: 't7-gran', x: 121, y: 958, sprite: 'npc3-old-woman-cane', face: 6, move: 'still', lines: ['In winter half this town boards up. It is a very different place then.'] },
  { id: 't7-chips', x: 121, y: 968, sprite: 'npc4-bowler-hat-man', face: 6, move: 'wander', r: 1, lines: ['A Wingull stole my chips again! They steal from everyone on the boardwalk.'] },
  { id: 't7-pika', x: 126, y: 959, sprite: 'npc4-ponytail-girl', face: 0, move: 'wander', r: 1, lines: ['A Pikachu and a Meowth hang around the boardwalk. Nobody minds.'] },
  { id: 't7-blowout', x: 135, y: 953, sprite: 'npc2-bearded-man', face: 6, move: 'still', lines: ['Sprucevale runs a Big Summer Blowout. Its big boss spends the season here, I hear.'] },
  { id: 't7-tourist', x: 119, y: 941, sprite: 'npc2-red-jacket-woman', face: 6, move: 'wander', r: 2, lines: ['Wide beach, boardwalk, ice cream and a little sunburn. Perfect.'] },

  // ---------- Tradeway: the crossroads market at the cave mouth (independent trade, cash and no questions; the stalls run on into the Route 4 cave) ----------
  { id: 't4-trader', x: 478, y: 771, sprite: 'npc4-bowler-hat-man', face: 6, move: 'wander', r: 2, lines: ['Every Cherimart in Kenora sells the same shelf. Here the shelf changes by the day.'] },
  { id: 't4-grower', x: 482, y: 771, sprite: 'npc3-bearded-man', face: 4, move: 'still', lines: ['I bring my crates in by the orchard cut. Cash on the nail, no questions.'] },
  { id: 't4-nick', x: 479, y: 776, sprite: 'npc2-green-shirt-kid', face: 0, move: 'wander', r: 2, lines: ['Watch for Nickit and Purrloin. They work the stalls better than the traders do.'] },
  { id: 't4-cross', x: 446, y: 772, sprite: 'npc3-white-haired-man', face: 2, move: 'still', lines: ['Every road in Kenora meets here. Dead centre of the region.'] },
  { id: 't4-freight', x: 459, y: 771, sprite: 'npc3-bearded-man', face: 6, move: 'still', lines: ['The freight run to Aldermere leaves from here. Every Cherimart shelf starts on it.'] },
  { id: 't4-timber', x: 435, y: 772, sprite: 'npc2-jumpsuit-man', face: 2, move: 'wander', r: 1, lines: ['Pinegrove timber stacks up at this end of the road. Tools and supplies go back down.'] },
  { id: 't4-claystone', x: 465, y: 772, sprite: 'npc2-pink-suit-man', face: 0, move: 'still', lines: ['Claystone sends its finds down the spoil road. They sell here first.'] },
  { id: 't4-mouth', x: 484, y: 771, sprite: 'npc4-vest-boy', face: 2, move: 'wander', r: 1, lines: ['The first stalls stood in the cave mouth, in the shade. Now they go a long way in.'] },
  { id: 't4-scarf', x: 441, y: 772, sprite: 'npc1-striped-dress-girl', face: 0, move: 'wander', r: 2, lines: ['Purrloin took my scarf at the stalls. I bought it back from the stall next door.'] },
  { id: 't4-dark', x: 471, y: 782, sprite: 'npc2-purple-top-woman', face: 4, move: 'still', lines: ['Past the last stall the road gets dark. I stop at the last stall.'] },
  { id: 't4-cash', x: 450, y: 761, sprite: 'npc3-old-woman-cane', face: 0, move: 'still', lines: ['Cash is cash in Tradeway. Nobody asks who earned it.'] },

  // ---------- Sailsport and Aldermere City: the supply path between them (docs/TRAVEL.md): a paid supply mount, works on the path only; each handler stands where the town meets the freight run, Sailsport's at the shore ----------
  { id: 't2-ride', x: 939, y: 734, sprite: 'npc4-sailor', face: 0, move: 'still', script: 'rent', name: 'Freight crew', lines: ['Freight goes up to Aldermere City every day along the supply path.', 'A supply mount is for hire. It stays on the path, and goes home if you leave it.'] },
  { id: 'g5-ride', x: 891, y: 585, sprite: 'delivery', face: 0, move: 'still', script: 'rent', name: 'Freight crew', lines: ['Everything Sailsport ships ends up here, and the supply path is how it arrives.', 'A supply mount is for hire. It stays on the path, and goes home if you leave it.'] },

  // ---------- Classes (docs/TRAVEL.md): a town teacher takes money and sets the easy lesson (a bar with a moving marker). Each skill is taught in at least two places: here and on a route (the trainers on Routes 6 and 7 once beaten) ----------
  { id: 't2-rough', x: 921, y: 713, sprite: 'npc1-red-cap-man', face: 2, move: 'still', script: 'class', skill: 'rough', name: 'Horseshoe Freights hand', lines: ['Horseshoe Freights runs heavy stock over rock and scrub all week.', 'I teach rough riding to anyone who will put in the practice. Want a lesson?'], known: ['You have the knack. Keep a heavy mount for rocky ground.'] },
  { id: 't2-dune', x: 927, y: 713, sprite: 'npc4-vest-boy', face: 6, move: 'still', script: 'class', skill: 'dune', name: 'Coast guide', lines: ['The Route 24 coast is soft sand all the way. A good mount does not slow down in it.', 'I teach dune riding. Want a lesson?'], known: ['You have the knack. Sand will not slow your mount now.'] },
  { id: 'g5-canter', x: 886, y: 582, sprite: 'npc4-blonde-girl', face: 2, move: 'still', script: 'class', skill: 'canter', name: 'Riding mistress', lines: ['Fast mounts are a point of pride in Aldermere City.', 'I teach cantering. Want a lesson?'], known: ['You have the knack. Open land and good roads are yours.'] },
  { id: 'g4-boulder', x: 523, y: 585, sprite: 'npc3-bearded-man', face: 2, move: 'still', script: 'class', skill: 'boulder', name: 'Quarry foreman', lines: ['Claystone is a quarry town. The stone faces here are climbed by the sure-footed.', 'I teach bouldering riding. Want a lesson?'], known: ['You have the knack. Climbers go where wheels cannot.'] },
  { id: 'g1-dune', x: 367, y: 349, sprite: 'npc1-explorer', face: 2, move: 'still', script: 'class', skill: 'dune', name: 'Desert guide', lines: ['Dunereach is all sand. Out here you ride it or you wade it.', 'I teach dune riding. Want a lesson?'], known: ['You have the knack. Sand will not slow your mount now.'] },
  { id: 'g2-snow', x: 795, y: 375, sprite: 'npc3-old-man-cane', face: 2, move: 'still', script: 'class', skill: 'snow', name: 'Snow guide', lines: ['Sprucevale gets deep snow. The right mount crosses it without slowing.', 'I teach snow riding. Want a lesson?'], known: ['You have the knack. Deep snow will not slow your mount now.'] },
  { id: 't1-snow', x: 576, y: 385, sprite: 'npc1-backwards-cap-boy', face: 2, move: 'still', script: 'class', skill: 'snow', name: 'Snow guide', lines: ['Frostfall lives on its snow. We teach snow riding to anyone who asks.', 'Want a lesson?'], known: ['You have the knack. Deep snow will not slow your mount now.'] },
  { id: 't1-fly', x: 582, y: 385, sprite: 'npc1-explorer', face: 6, move: 'still', script: 'class', skill: 'fly', name: 'Flight Hub instructor', fee: 2000, lines: ['This is the Flight Hub. We teach flying to trainers whose lead can learn Fly.', 'Want a lesson?'], known: ['You know how now. Press G to take off, and land on clear outdoor ground.'] },

  // ---------- Route 6: the seafront strip (the resort has spilled up the coast and taken the road; the dock and the castles; Lady, Sailor, Lass, Youngster) ----------
  { id: 'r6-dock', x: 104, y: 924, sprite: 'fishing2', face: 4, move: 'still', lines: ['Nothing out past the breakers is catchable from here. Shore and dock fishing only.', 'For the deep stuff, go to Salt Bay and learn to surf properly.'] },
  { id: 'r6-mum', x: 114, y: 916, sprite: 'npc3-apron-woman', face: 6, move: 'still', lines: ['Kids build sandcastles and wander off. Then the castles start dragging things under.', 'Keep well back from them, dear.'] },
  { id: 'r6-pearl', x: 150, y: 961, sprite: 'npc2-red-jacket-woman', face: 0, move: 'still', lines: ['Do mind my parasol. The sun here is relentless.'],
    trainer: { cls: 'Lady', name: 'Pearl', avatar: 'lady', sight: 5, money: 24, team: [['wingull', 0], ['krabby', 1], ['wingull', 1], ['sandygast', 2], ['krabby', 2], ['chinchou', 3]], say: 'The resort has crept all the way up the road. Care for a battle?', lose: 'Oh dear. Pass me my sunscreen.' } },
  { id: 'r6-brine', x: 160, y: 972, sprite: 'npc4-sailor', face: 4, move: 'still', script: 'coach', skill: 'fly', name: 'Brine', coach: ['Gulls and winged Pokemon come in off the water here. I can teach you to fly with one.', 'Pay me, or take the hard lesson.'], known: ['You fly well. Keep an eye out for the gulls.'], lines: ['We put in at Longshore for the ice cream.'],
    trainer: { cls: 'Sailor', name: 'Brine', avatar: 'sailor', sight: 5, money: 20, team: [['wimpod', 0], ['wingull', 1], ['krabby', 1], ['wimpod', 2], ['chinchou', 2], ['wingull', 3]], say: 'Shore leave! Let us make it a short battle.', lose: 'Back to the ship for me.' } },
  { id: 'r6-kit', x: 172, y: 961, sprite: 'npc2-pink-top-girl', face: 0, move: 'still', lines: ['I got sunburnt on day one. Worth it.'],
    trainer: { cls: 'Lass', name: 'Kit', avatar: 'lass', sight: 5, money: 24, team: [['krabby', 0], ['wingull', 1], ['sandygast', 1], ['wimpod', 2], ['krabby', 2], ['wingull', 3]], say: 'You are already on holiday, you know. Battle?', lose: 'My shoulders hurt, and now my pride.' } },
  { id: 'r6-tom', x: 184, y: 960, sprite: 'npc3-striped-boy', face: 0, move: 'still', lines: ['Mind the sandcastles. They are not always just sand.'],
    trainer: { cls: 'Youngster', name: 'Tom', avatar: 'youngster', sight: 5, money: 16, team: [['sandygast', 0], ['krabby', 1], ['sandygast', 1], ['wingull', 2], ['wimpod', 2], ['sandygast', 3]], say: 'Stay off the sandcastles! And take me on while you are here.', lose: 'My castle fell down too.' } },

  // ---------- Pinegrove: villagers (the logging town; every stand numbered, the mill never idle, the cold silence with Claystone) ----------
  { id: 'g6-feller', x: 611, y: 871, sprite: 'npc2-jumpsuit-man', face: 4, move: 'still', lines: ['The mill saws whatever comes down Route 111. It never really stops.'] },
  { id: 'g6-stands', x: 601, y: 870, sprite: 'npc2-purple-top-woman', face: 0, move: 'wander', r: 2, lines: ['Every stand has a number. You can read the whole rotation off the trees.'] },
  { id: 'g6-seedling', x: 592, y: 871, sprite: 'npc1-ponytail-girl', face: 2, move: 'wander', r: 3, lines: ['The seedlings go in the beds south of town. I water them before school.'] },
  { id: 'g6-haul', x: 625, y: 871, sprite: 'delivery', face: 6, move: 'still', lines: ['Timber goes out on the east road. Tools and supplies come back the same way.'] },
  { id: 'g6-reader', x: 606, y: 861, sprite: 'npc5-old-man', face: 0, move: 'still', lines: ['Past the last house you can read the forest. Fresh cut, replanted, or left alone.'] },
  { id: 'g6-stump', x: 606, y: 880, sprite: 'npc2-red-shirt-boy', face: 4, move: 'wander', r: 3, lines: ['Keep clear of the old stumps after dark. That is all I will say.'] },
  { id: 'g6-silence', x: 600, y: 876, sprite: 'npc1-green-shirt-man', face: 0, move: 'still', lines: ['Nobody here trades with Claystone. Nobody here says why, either.'] },
  { id: 'g6-kleavor', x: 590, y: 858, sprite: 'npc3-old-woman-cane', face: 0, move: 'still', lines: ['Aspen has the only Kleavor in Kenora. She earned it the long way.'] },
  { id: 'g6-gymkid', x: 621, y: 866, sprite: 'npc5-striped-boy', face: 2, move: 'wander', r: 2, lines: ['That big mill is the gym. Aspen runs it herself.'] },
  { id: 'g6-notice', x: 602, y: 874, sprite: 'npc1-green-shirt-man', face: 4, move: 'still', lines: ['The board lists every stand and its date. Felled, replanted, left alone.'] },

  // ---------- Route 3: the working forest (lumberjacks, a forester, a bug catcher and a picnicker among the numbered stands) ----------
  { id: 'r3-pike', x: 601, y: 792, sprite: 'npc1-red-cap-man', face: 2, move: 'still', lines: ['Every felled stand gets replanted. That is the rule here.'],
    trainer: { cls: 'Lumberjack', name: 'Pike', avatar: 'hiker', sight: 5, money: 24, team: [['bonsly',0],['machop',1],['bonsly',1],['seedot',2],['machop',2],['heracross',3]], say: 'This stand comes down today. Care to test your Pokemon against my axe?', lose: 'Clean cut. You stood like an old oak.' } },
  { id: 'r3-wren', x: 611, y: 800, sprite: 'npc1-headband-boy', face: 6, move: 'still', lines: ['The Burmy here wear bark. In town they wear sawdust.'],
    trainer: { cls: 'Bug Catcher', name: 'Wren', avatar: 'bugcatcher', sight: 5, money: 16, team: [['burmy',0],['heracross',1],['burmy',1],['bonsly',2],['heracross',2],['burmy',3]], say: 'Burmy dress up in whatever the stand is made of. Want a battle?', lose: 'My Burmy lost its cloak!' } },
  { id: 'r3-tuck', x: 602, y: 810, sprite: 'npc3-white-haired-man', face: 2, move: 'still', lines: ['The numbers on the markers tell you what is next for each stand.'],
    trainer: { cls: 'Forester', name: 'Tuck', avatar: 'hiker', sight: 5, money: 24, team: [['seedot',0],['bonsly',1],['seedot',1],['chikorita',2],['machop',2],['seedot',3]], say: 'I replant what I fell. Let us see what you have grown!', lose: 'Good roots. You will go far.' } },
  { id: 'r3-sorrel', x: 611, y: 816, sprite: 'npc3-cap-girl', face: 6, move: 'still', lines: ['It is quiet out here once the saws stop.'],
    trainer: { cls: 'Picnicker', name: 'Sorrel', avatar: 'picnicker', sight: 5, money: 24, team: [['seedot',0],['burmy',1],['bonsly',1],['chikorita',2],['seedot',2],['bonsly',3]], say: 'Lunch among the stumps. They do not mind. Battle?', lose: 'Oh no, my sandwich!' } },

  // ---------- Route 111: the timber haul (landings, trucks and a loader; teamsters, a bug catcher, a fisherman, a hiker) ----------
  { id: 'r111-dale', x: 650, y: 867, sprite: 'npc3-bearded-man', face: 0, move: 'still', lines: ['Landings every few hundred metres. Load, haul, come back.'],
    trainer: { cls: 'Teamster', name: 'Dale', avatar: 'hiker', sight: 5, money: 24, team: [['timburr',0],['slowpoke',1],['timburr',1],['sewaddle',2],['slowpoke',2],['timburr',3]], say: 'I haul logs down this road every day. A battle is a short break.', lose: 'Dropped the load. Well fought.' } },
  { id: 'r111-perry', x: 665, y: 876, sprite: 'npc1-headband-boy', face: 4, move: 'still', lines: ['Check the log stacks. There is always something clinging on.'],
    trainer: { cls: 'Bug Catcher', name: 'Perry', avatar: 'bugcatcher', sight: 5, money: 16, team: [['sewaddle',0],['pineco',1],['sewaddle',1],['joltik',2],['pineco',2],['sewaddle',3]], say: 'Pineco hang off the log stacks along the landings. Battle?', lose: 'My Pineco came off the stack!' } },
  { id: 'r111-moss', x: 682, y: 867, sprite: 'fishing', face: 0, move: 'still', lines: ['The trucks do not scare the fish. Nothing scares the fish.'],
    trainer: { cls: 'Fisherman', name: 'Moss', avatar: 'fisherman', sight: 5, money: 20, team: [['magikarp',0],['krabby',1],['magikarp',1],['chinchou',2],['krabby',2],['squirtle',3]], say: 'I fish the water beside the haul road. Care to try your luck on me?', lose: 'Nothing biting today, not even you.' } },
  { id: 'r111-quill', x: 700, y: 876, sprite: 'npc1-explorer', face: 4, move: 'still', lines: ['Pinegrove timber ends up all over Kenora. It starts on this road.'],
    trainer: { cls: 'Hiker', name: 'Quill', avatar: 'hiker', sight: 5, money: 24, team: [['timburr',0],['purrloin',1],['timburr',1],['slowpoke',2],['purrloin',2],['timburr',3]], say: 'The haul road is a long walk. A battle makes it shorter!', lose: 'You wore me down.' } },
  // ---------- Spindlewood: the timber dock (quay, crane, log yards and the cove; people tell what an ordinary visitor sees, nothing about the boats' real business) ----------
  { id: 't6-crane', x: 759, y: 849, sprite: 'npc2-jumpsuit-man', face: 0, move: 'still', lines: ['That crane lifts a whole stack in one go. It has hardly stopped since dawn.'] },
  { id: 't6-tally', x: 751, y: 846, sprite: 'npc2-striped-shirt-man', face: 2, move: 'still', lines: ['Every load on or off this quay gets tallied. A busy day is a long day.'] },
  { id: 't6-sawdust', x: 746, y: 846, sprite: 'npc2-pink-suit-man', face: 0, move: 'wander', r: 1, lines: ['Sawdust and salt. You stop smelling either after the first week.'] },
  { id: 't6-rot', x: 737, y: 843, sprite: 'npc3-old-man-cane', face: 0, move: 'still', lines: ['Rot is the enemy. One damp log and the buyers send the whole load back.'] },
  { id: 't6-pinegrove', x: 743, y: 841, sprite: 'delivery', face: 6, move: 'wander', r: 1, lines: ['Every log on this quay came down Route 111 stamped with the Pinegrove mark.'] },
  { id: 't6-fungus', x: 727, y: 843, sprite: 'npc1-blue-haired-boy', face: 0, move: 'wander', r: 2, lines: ['Some people think we are the fungus town. We are not. We just have a lot of boats.'] },
  { id: 't6-gull', x: 747, y: 842, sprite: 'npc4-ponytail-girl', face: 2, move: 'wander', r: 1, lines: ['Wingull sit on every post and steal lunch. Hold on to your sandwich!'] },
  { id: 't6-wimpod', x: 759, y: 844, sprite: 'npc2-yellow-shirt-boy', face: 0, move: 'wander', r: 1, lines: ['Wimpod scuttle about under the boards. Drop a crumb and they all come out to look.'] },
  { id: 't6-night', x: 751, y: 854, sprite: 'npc3-old-woman-cane', face: 2, move: 'still', lines: ['At night a big Golisopod walks right out onto the wharf. We just step round it.'] },
  { id: 't6-craft', x: 772, y: 849, sprite: 'npc4-sailor', face: 2, move: 'still', lines: ['Boats in and out all day. A cove this size fills up fast.'] },
  { id: 't6-cove', x: 755, y: 854, sprite: 'npc4-sailor', face: 0, move: 'still', lines: ['Tentacool drift into the cove on the tide. At night Chinchou glow under the boards.'] },
  { id: 't6-yard', x: 747, y: 857, sprite: 'npc2-pink-suit-man', face: 0, move: 'still', lines: ['Pineco hang off the log stacks and Nickit nick tools. Count your gear at the end of the day.'] },
  // ---------- Sporehaven: villagers (a settlement that keeps its lamps low and lets the forest outshine it; caretakers, not cultists; nothing here is story-gated) ----------
  { id: 'g8-lamps', x: 625, y: 999, sprite: 'npc3-old-woman-cane', face: 0, move: 'still', lines: ['We keep our lamps low here. The forest does the shining, and it does it better.'] },
  { id: 'g8-warden', x: 633, y: 997, sprite: 'npc1-green-shirt-man', face: 6, move: 'still', lines: ['A warden clears, treats and patrols. Nobody thanks us for it, and we do it anyway.'] },
  { id: 'g8-line', x: 621, y: 997, sprite: 'npc2-bearded-man', face: 0, move: 'still', lines: ['The east road runs to Duskmoss. We cut the fungus back along it and put up no sign.'] },
  { id: 'g8-night', x: 641, y: 982, sprite: 'npc2-red-jacket-woman', face: 0, move: 'wander', r: 2, lines: ['Walk out at night. The wood is the lit thing and the town is the dark one. We like it so.'] },
  { id: 'g8-kid', x: 610, y: 982, sprite: 'npc4-brown-haired-boy', face: 0, move: 'wander', r: 2, lines: ['That big cap is the gym. Rue runs it herself. Her Breloom is the one everybody remembers.'] },
  { id: 'g8-foongus', x: 627, y: 987, sprite: 'npc4-blonde-girl', face: 0, move: 'wander', r: 1, lines: ['See a Poke Ball on the path? Look twice. Some are Foongus. The forest does its own defending.'] },
  { id: 'g8-forager', x: 607, y: 1002, sprite: 'npc1-ponytail-girl', face: 0, move: 'wander', r: 2, lines: ['Morelull glow at the edge of every clearing. We leave them be, and they leave us be.'] },
  { id: 'g8-pools', x: 647, y: 1002, sprite: 'fishing', face: 0, move: 'wander', r: 1, lines: ['There is standing water between the caps all the way down Route 2. Wooper love it.'] },
  { id: 'g8-spindle', x: 649, y: 997, sprite: 'npc1-red-cap-man', face: 4, move: 'still', lines: ['Spindlewood is not the fungus town. We are. They just have the boats.'] },
  { id: 'g8-route2', x: 597, y: 997, sprite: 'npc5-old-man', face: 0, move: 'still', lines: ['Route 2 starts the moment you leave town. You are in the forest the whole way.'] },
  { id: 'g8-dusk', x: 657, y: 997, sprite: 'npc4-sailor', face: 0, move: 'still', lines: ['Our crews go down to Duskmoss to hold the line. They are welcome there, and always have been.'] },
  { id: 'g8-drift', x: 618, y: 982, sprite: 'npc3-apron-woman', face: 0, move: 'wander', r: 2, lines: ['Spores drift. The line holds, but not perfectly. If something glows, word goes up the road.'] },

  // ---------- Route 2: the mushroom route (the fungal forest the whole way; damp ground, standing water between the caps, nothing hunts and everything waits) ----------
  { id: 'r2-wynne', x: 574, y: 978, sprite: 'npc2-pink-top-girl', face: 0, move: 'still', lines: ['The ground is soft and damp out here. It grows everything.'],
    trainer: { cls: 'Forager', name: 'Wynne', avatar: 'picnicker', sight: 5, money: 24, team: [['foongus',0],['morelull',1],['wooper',1],['foongus',2],['morelull',2],['tangela',3]], say: 'Nothing on this road hunts. Everything waits. So do I, for a challenger!', lose: 'You were worth the wait.' } },
  { id: 'r2-bram', x: 578, y: 963, sprite: 'fishing2', face: 0, move: 'still', lines: ['Water pools between the caps all the way down this road.'],
    trainer: { cls: 'Fisherman', name: 'Bram', avatar: 'fisherman', sight: 5, money: 20, team: [['wooper',0],['wooper',1],['foongus',1],['wooper',2],['tangela',2],['wooper',3]], say: 'Wooper live in the standing water. So do my best catches!', lose: 'My line was never going to hold.' } },
  { id: 'r2-orlo', x: 581, y: 948, sprite: 'npc1-explorer', face: 0, move: 'still', lines: ['It glows brighter out here at night than the town ever does.'],
    trainer: { cls: 'Hiker', name: 'Orlo', avatar: 'hiker', sight: 5, money: 24, team: [['tangela',0],['foongus',1],['morelull',1],['tangela',2],['wooper',2],['foongus',3]], say: 'I have walked this road a hundred times and it still glows new. Battle?', lose: 'A hundred walks did not prepare me for you.' } },
  { id: 'r2-pip', x: 607, y: 918, sprite: 'npc4-vest-boy', face: 0, move: 'still', lines: ['Nothing on the fungal floor chases you. It just waits.'],
    trainer: { cls: 'Bug Catcher', name: 'Pip', avatar: 'bugcatcher', sight: 5, money: 16, team: [['morelull',0],['foongus',1],['morelull',1],['foongus',2],['morelull',2],['foongus',3]], say: 'Foongus and Morelull live under the caps. Want to meet them?', lose: 'My mushrooms wilted!' } },

  // ---------- Route 101: the quarantine line (the crews' road; the fungus is cut back along it, thinning toward Duskmoss; it is maintained and not advertised) ----------
  { id: 'r101-sedge', x: 690, y: 999, sprite: 'npc3-bearded-man', face: 0, move: 'still', lines: ['Cut it back, treat the stumps, move on. That is the whole job.'],
    trainer: { cls: 'Warden', name: 'Sedge', avatar: 'hiker', sight: 5, money: 24, team: [['stunky',0],['shroomish',1],['croagunk',1],['toedscool',2],['stunky',2],['shroomish',3]], say: 'We cut the fungus back along this road every week. You are in my section!', lose: 'Clean cut. Well done.' } },
  { id: 'r101-tamsin', x: 712, y: 1005, sprite: 'npc1-explorer', face: 4, move: 'still', lines: ['The glow thins out toward Duskmoss because we make it. Not because it wants to.'],
    trainer: { cls: 'Warden', name: 'Tamsin', avatar: 'backpacker', sight: 5, money: 24, team: [['croagunk',0],['stunky',1],['shroomish',1],['croagunk',2],['toedscool',2],['stunky',3]], say: 'I patrol this stretch daily. Nothing gets by me. Not even a trainer!', lose: 'I could not hold the line against you.' } },
  { id: 'r101-flint', x: 734, y: 999, sprite: 'npc1-explorer', face: 0, move: 'still', lines: ['Nobody puts up signs for this road. It does not need advertising.'],
    trainer: { cls: 'Hiker', name: 'Flint', avatar: 'hiker', sight: 5, money: 24, team: [['stunky',0],['croagunk',1],['stunky',1],['shroomish',2],['toedscool',2],['croagunk',3]], say: 'Long road, quiet crews. A battle breaks it up nicely.', lose: 'You wore me out.' } },
  { id: 'r101-ivo', x: 744, y: 1006, sprite: 'doctor', face: 4, move: 'still', lines: ['By Duskmoss there is hardly any glow left. That is the point.'],
    trainer: { cls: 'Scientist', name: 'Ivo', avatar: 'scientist', sight: 5, money: 24, team: [['shroomish',0],['toedscool',1],['stunky',1],['croagunk',2],['shroomish',2],['toedscool',3]], say: 'I treat the cut ends so nothing regrows. Mind the slippery bits!', lose: 'Well. That was an unexpected result.' } },

  // ---------- Duskmoss: villagers (the town at the end of the road; Sporehaven keeps the line, the town knows what it owes them; the sea side is ordinary; nothing here is story-gated) ----------
  { id: 't8-glow', x: 767, y: 1030, sprite: 'npc3-old-man-orange', face: 0, move: 'still', lines: ['At night there is a wall of soft light where the forest starts. We are the dark part.'] },
  { id: 't8-warden', x: 771, y: 1040, sprite: 'npc1-green-shirt-man', face: 6, move: 'still', lines: ['Sporehaven crews cut and treat the line all week. Duskmoss has always been glad to see us.'] },
  { id: 't8-treat', x: 766, y: 1026, sprite: 'npc2-jumpsuit-man', face: 6, move: 'still', lines: ['Cut it back, treat the stumps, move on. The line holds, but not perfectly.'] },
  { id: 't8-kid', x: 757, y: 1044, sprite: 'npc4-brown-haired-boy', face: 0, move: 'wander', r: 2, lines: ['Something on our fence started glowing last week. Mum sent word up the road.'] },
  { id: 't8-gran', x: 748, y: 1044, sprite: 'npc3-old-woman-cane', face: 0, move: 'still', lines: ['I stopped seeing the glow years ago. I only look when someone new asks about it.'] },
  { id: 't8-sea', x: 786, y: 1047, sprite: 'fishing', face: 0, move: 'wander', r: 1, lines: ['The sea here is just the sea. After a day facing the other side, I like that.'] },
  { id: 't8-sailor', x: 784, y: 1044, sprite: 'npc4-sailor', face: 0, move: 'still', lines: ['Wingull and Mareanie on the shore, Shellos in the shallows. Nothing strange comes out of the water.'] },
  { id: 't8-spore', x: 764, y: 1048, sprite: 'npc2-purple-top-woman', face: 2, move: 'wander', r: 1, lines: ['See that mushroom in the square? It was not there last week. We are keeping an eye on it.'] },
  { id: 't8-goomy', x: 754, y: 1046, sprite: 'npc1-ponytail-girl', face: 0, move: 'wander', r: 2, lines: ['Goomy like the damp ground by the line. Tympole too. Mind the slippery bits.'] },
  { id: 't8-quiet', x: 790, y: 1044, sprite: 'npc2-yellow-suit-man', face: 4, move: 'still', lines: ['A quiet end of the road. People call that dull. I call it a place that is still here.'] },
  { id: 't8-night', x: 760, y: 1054, sprite: 'npc5-old-man', face: 0, move: 'still', lines: ['Duskull drift through after dark and Litwick light up the lanes. They mean no harm.'] },
  { id: 't8-boats', x: 779, y: 1046, sprite: 'npc3-apron-woman', face: 0, move: 'wander', r: 1, lines: ['Boats go out at dawn and come back by noon. Half the town eats what they bring in.'] },

  // ---------- Route 103: the black shore (dark sand and sea cliffs running west along the bottom edge; the least travelled coast, nothing is out here and nothing comes) ----------
  { id: 'r103-orm', x: 720, y: 1092, sprite: 'fishing', face: 2, move: 'still', lines: ['Nothing bites out here that anyone wants to talk about. It suits me.'],
    trainer: { cls: 'Fisherman', name: 'Orm', avatar: 'fisherman', sight: 5, money: 20, team: [['finneon',0],['magikarp',1],['staryu',1],['chinchou',2],['krabby',2],['finneon',3]], say: 'Quiet shore, quiet fish, and then you turn up. Battle?', lose: 'The tide has turned on me.' } },
  { id: 'r103-hale', x: 731, y: 1110, sprite: 'npc4-sailor', face: 6, move: 'still', lines: ['Dark sand all the way west. The least travelled coast in Kenora.'],
    trainer: { cls: 'Sailor', name: 'Hale', avatar: 'sailor', sight: 5, money: 24, team: [['staryu',0],['finneon',1],['krabby',1],['staryu',2],['chinchou',2],['krabby',3]], say: 'Nobody sails past here. You are the first face I have seen all week!', lose: 'Fair winds to you.' } },
  { id: 'r103-nell', x: 640, y: 1117, sprite: 'npc4-ponytail-girl', face: 0, move: 'still', lines: ['The cliffs above the beach hold nothing. I checked.'],
    trainer: { cls: 'Lass', name: 'Nell', avatar: 'lass', sight: 5, money: 24, team: [['finneon',0],['greavard',1],['staryu',1],['finneon',2],['greavard',2],['dreepy',3]], say: 'Nothing is out here and nothing comes. Except you!', lose: 'Well, that was something at last.' } },
  { id: 'r103-brin', x: 684, y: 1119, sprite: 'npc1-explorer', face: 0, move: 'still', lines: ['Greavard follow you along the sand at night. They never come close.'],
    trainer: { cls: 'Backpacker', name: 'Brin', avatar: 'backpacker', sight: 5, money: 24, team: [['greavard',0],['finneon',1],['greavard',1],['dreepy',2],['staryu',2],['greavard',3]], say: 'It gets lonely on this coast. A battle is company!', lose: 'Thank you for the company.' } },
  // ---------- Route 1: the road south to Quiet Plain (an old paved road, cracked end to end with the grass forced up through it; nobody walks it, one person keeps its waymarker stones legible from the far end; the strays that follow you south; no birds) ----------
  { id: 'r1-stone9', x: 535, y: 1015, sprite: null, face: 0, move: 'still', name: 'Waymarker', lines: ['A waymarker stone, cut with a 9. The edges are sharp.','Someone keeps these legible. The chips at the foot are still pale.'] },
  { id: 'r1-stone8', x: 536, y: 1037, sprite: null, face: 0, move: 'still', name: 'Waymarker', lines: ['A waymarker stone, cut with an 8. No moss on it at all.','Everything else on this road is going green, but not the numerals.'] },
  { id: 'r1-stone7', x: 532, y: 1049, sprite: null, face: 0, move: 'still', name: 'Waymarker', lines: ['A waymarker stone, cut with a 7. The cut is deep and clean.','The road is cracked end to end. The stones are not.'] },
  { id: 'r1-stone6', x: 517, y: 1044, sprite: null, face: 0, move: 'still', name: 'Waymarker', lines: ['A waymarker stone, cut with a 6. The chips are pale.','Whoever cuts these has been along this road more than once.'] },
  { id: 'r1-stone5', x: 518, y: 1061, sprite: null, face: 0, move: 'still', name: 'Waymarker', lines: ['A waymarker stone, cut with a 5. Halfway, near enough.','The numerals are the only thing on this road anyone looks after.'] },
  { id: 'r1-stone4', x: 504, y: 1062, sprite: null, face: 0, move: 'still', name: 'Waymarker', lines: ['A waymarker stone, cut with a 4. The edges are crisp.','It counts down, one stone at a time, toward the south.'] },
  { id: 'r1-stone3', x: 498, y: 1072, sprite: null, face: 0, move: 'still', name: 'Waymarker', lines: ['A waymarker stone, cut with a 3. Fresh pale chips lie at its foot.','Nobody walks this road, but someone keeps the numbers right.'] },
  { id: 'r1-stone2', x: 494, y: 1082, sprite: null, face: 0, move: 'still', name: 'Waymarker', lines: ['A waymarker stone, cut with a 2. The edges are sharp.','You can see the open plain from here.'] },
  { id: 'r1-stone1', x: 487, y: 1093, sprite: null, face: 0, move: 'still', name: 'Waymarker', lines: ['A waymarker stone, cut with a 1. The edges are sharp.','The last one. Whoever cuts these is not far off.'] },
  { id: 'r1-wick', x: 526, y: 1001, sprite: 'npc2-red-shirt-boy', face: 2, move: 'still', lines: ['The strays on this road walk south with you. They never walk back.'],
    trainer: { cls: 'Youngster', name: 'Wick', avatar: 'youngster', sight: 5, money: 16, team: [['rattata', 0], ['lillipup', 1], ['rattata', 1], ['lillipup', 2], ['nickit', 2], ['lillipup', 3]], say: 'Mind the cracks. Half this road is held together by weeds!', lose: 'The weeds held up better than I did.' } },
  { id: 'r1-edie', x: 523, y: 1019, sprite: 'npc1-ponytail-girl', face: 6, move: 'still', lines: ['No birds out here. Nothing ever perches on this road.'],
    trainer: { cls: 'Lass', name: 'Edie', avatar: 'lass', sight: 5, money: 24, team: [['oddish', 0], ['oddish', 1], ['gastly', 1], ['oddish', 2], ['gastly', 2], ['duskull', 3]], say: 'It is very quiet on this road. Shall we change that?', lose: 'Quiet again. I should not have spoken.' } },
  { id: 'r1-corwin', x: 532, y: 1040, sprite: 'npc1-explorer', face: 2, move: 'still', lines: ['Somebody built this road to last. Then they stopped coming.'],
    trainer: { cls: 'Hiker', name: 'Corwin', avatar: 'hiker', sight: 5, money: 24, team: [['nickit', 0], ['lillipup', 1], ['nickit', 1], ['rattata', 2], ['lillipup', 2], ['nickit', 3]], say: 'I walk it end to end every year. The weeds win a little more each time.', lose: 'The weeds always win. So do you.' } },
  { id: 'r1-mabel', x: 495, y: 1085, sprite: 'npc4-blonde-girl', face: 6, move: 'still', lines: ['The strays walk you down to the end. Something else waits there.'],
    trainer: { cls: 'Picnicker', name: 'Mabel', avatar: 'picnicker', sight: 5, money: 24, team: [['lillipup', 0], ['lillipup', 1], ['duskull', 1], ['nickit', 2], ['gastly', 2], ['lillipup', 3]], say: 'The strays brought me this far. Want to see what they taught me?', lose: 'Even the strays are impressed.' } },

  // ---------- Quiet Plain: the memorial (open grass, markers, a great deal of wind; nobody guards it and nothing gates it; the ghost-speaker teaches Sensing Shadow Pokemon to anyone who walks down, and their name is still open) ----------
  { id: 'l4-speaker', x: 488, y: 1108, sprite: 'npc1-robed-woman', face: 6, move: 'still', script: 'teach', skill: 'sense', name: 'Ghost-speaker', lines: ['Nobody sent you and nothing stopped you. Walking all the way down is all this place asks.', 'The dead here remember how that darkness felt. They taught me to spot it. I was not there. Listen?'], known: ['The Curse has come before. This plain is what the region built after, and it has stayed open.', 'I was not there. I only repeat what the dead tell me, and they do not always keep to the order.'] },
  { id: 'l4-wind', x: 481, y: 1106, sprite: 'npc5-old-man', face: 0, move: 'still', lines: ['There is always wind out here. You stop hearing it after a while.', 'Whoever cuts the road stones works alone out here. I have never seen them take a rest.'] },
  { id: 'l4-flowers', x: 494, y: 1116, sprite: 'npc3-old-woman-cane', face: 6, move: 'still', lines: ['I bring flowers every year. My mother did, and hers. Nobody ever told me who they are for.'] },
  { id: 'l4-count', x: 481, y: 1119, sprite: 'npc2-green-shirt-kid', face: 0, move: 'still', lines: ['Dad says it is just a nice walk. I counted the stones and got a different number twice.'] },
  { id: 'l4-habit', x: 486, y: 1117, sprite: 'npc3-bearded-man', face: 0, move: 'wander', r: 1, lines: ['Most of us could not tell you what the markers are for.', 'We come anyway. The habit outlived the reason.'] },
];
